// Detecta qual gatilho disparou este workflow
let tipo;
try {
  $('Gatilho - Semanal Seg 06h').first();
  tipo = 'SEMANAL';
} catch(e) {
  tipo = 'DIARIO';
}

const now = new Date();
let inicio, fim;

if (tipo === 'SEMANAL') {
  // Semana atual: segunda a domingo
  const segunda = new Date(now);
  // Volta para segunda-feira da semana atual
  const diff = now.getDay() === 0 ? 6 : now.getDay() - 1;
  segunda.setDate(now.getDate() - diff);
  segunda.setHours(0, 0, 0, 0);
  const domingo = new Date(segunda);
  domingo.setDate(segunda.getDate() + 6);
  domingo.setHours(23, 59, 59, 999);
  inicio = segunda.toISOString();
  fim = domingo.toISOString();
} else {
  // Período: hoje
  const hojeInicio = new Date(now);
  hojeInicio.setHours(0, 0, 0, 0);
  const hojeFim = new Date(now);
  hojeFim.setHours(23, 59, 59, 999);
  inicio = hojeInicio.toISOString();
  fim = hojeFim.toISOString();
}

// Data formatada em pt-BR
const dataFormatada = now.toLocaleDateString('pt-BR', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

return [{ json: { inicio, fim, tipo, dataFormatada } }];

// Recupera período
const periodo = $('Code - Determinar Período').first().json;
const { tipo, inicio, fim, dataFormatada } = periodo;

// Busca os eventos direto do Calendar
const calendarItems = $('Google Calendar - Buscar Eventos').all();
const calendarEvents = [];

for (const item of calendarItems) {
  const d = item.json;
  // Ignora se for o item vazio do 'Always Output Data'
  if (Object.keys(d).length === 0) continue;

  if (d.summary !== undefined || d.start !== undefined) {
    calendarEvents.push({
      titulo: d.summary || 'Sem título',
      inicio: d.start?.dateTime || d.start?.date || '',
      fim: d.end?.dateTime || d.end?.date || '',
      descricao: d.description || '',
      local: d.location || ''
    });
  }
}

// Busca os registros direto da Planilha
const sheetsItems = $('Google Sheets - Buscar Histórico').all();
const sheetsRecords = [];

for (const item of sheetsItems) {
  const d = item.json;
  if (Object.keys(d).length === 0) continue;
  sheetsRecords.push(d);
}

// Filtra sheets pelo período
const inicioDate = new Date(inicio);
const fimDate = new Date(fim);
const sheetsFiltrados = sheetsRecords.filter(row => {
  const dataRow = new Date(row.Data || row.DataEvento || row['Data do Evento'] || '');
  return dataRow >= inicioDate && dataRow <= fimDate;
});

// Função de prioridade
function getPrioridade(texto) {
  const t = (texto || '').toLowerCase();
  if (t.includes('audiência') || t.includes('audiencia')) return 1;
  if (t.includes('intimação') || t.includes('intimacao')) return 2;
  if (t.includes('prazo fatal')) return 3;
  if (t.includes('prazo')) return 4;
  return 5;
}

// Ordena eventos
calendarEvents.sort((a, b) => {
  const pa = getPrioridade(a.titulo + ' ' + a.descricao);
  const pb = getPrioridade(b.titulo + ' ' + b.descricao);
  if (pa !== pb) return pa - pb;
  return new Date(a.inicio) - new Date(b.inicio);
});

const totalEventos = calendarEvents.length;

// System prompt
const systemPrompt = `Você é um assistente jurídico que organiza compromissos para um advogado.\nSempre use markdown compatível com Telegram (negrito com *, itálico com _, etc.).\nOrdenação OBRIGATÓRIA de prioridade:\n⚖️ 1. Audiências\n📨 2. Intimações\n🚨 3. Urgentes\n📌 4. Outros compromissos\nSeja conciso, profissional e claro. Use emojis para facilitar a leitura.`;

// User prompt
let userPrompt;
if (tipo === 'SEMANAL') {
  userPrompt = `Hoje é ${dataFormatada}.\nCrie um *RESUMO SEMANAL COMPLETO* da semana atual.\n\nCOMPROMISSOS DA SEMANA (já ordenados por prioridade):\n${JSON.stringify(calendarEvents, null, 2)}\n\nHISTÓRICO RELEVANTE DA PLANILHA:\n${JSON.stringify(sheetsFiltrados.slice(0, 15), null, 2)}\n\nINSTRUÇÕES:\n- Agrupe por dia da semana (Segunda a Domingo)\n- Dentro de cada dia, respeite a ordem de prioridade\n- No INÍCIO do resumo, destaque os 3 compromissos mais críticos da semana\n- No FIM, inclua contadores: total de eventos, audiências, intimações e prazos`;
} else {
  userPrompt = `Hoje é ${dataFormatada}.\nCrie um *RESUMO DIÁRIO* dos compromissos de hoje.\n\nCOMPROMISSOS DE HOJE (já ordenados por prioridade):\n${JSON.stringify(calendarEvents, null, 2)}\n\nHISTÓRICO RELEVANTE DA PLANILHA:\n${JSON.stringify(sheetsFiltrados.slice(0, 10), null, 2)}\n\nINSTRUÇÕES:\n- Liste em ordem de prioridade (Audiência > Intimação > Prazo Fatal > Outros)\n- Para cada item inclua: horário, tipo de ato, processo (se houver) e tribunal\n- No FIM, inclua: ${totalEventos} compromisso(s) no total`;
}

return [{
  json: {
    totalEventos,
    tipo,
    dataFormatada,
    inicio,
    fim,
    systemPrompt,
    userPrompt,
    calendarEvents
  }
}];

// Recupera resposta da IA e dados do período
let aiContent = $json.choices[0].message.content;
const prepNode = $('Code - Preparar Dados para IA').first().json;
const { tipo, dataFormatada, totalEventos } = prepNode;

// Remove apenas os # de cabeçalho
aiContent = aiContent.replace(/^#{1,3}\s*/gm, '');

// Cabeçalho conforme tipo
const emoji = tipo === 'SEMANAL' ? '📅' : '🗓️';
const tituloPrincipal = tipo === 'SEMANAL'
  ? `${emoji} *RESUMO SEMANAL*`
  : `${emoji} *RESUMO DO DIA*`;

const subtitulo = `${dataFormatada}`;
const separador = '─────────────────';

// Monta mensagem final
const mensagem = `${tituloPrincipal}\n${subtitulo}\n${separador}\n\n${aiContent}\n\n${separador}\n✉️ Gerado automaticamente pela sua Assistente Virtual`;

// Assunto do email
const assunto = tipo === 'SEMANAL'
  ? `📅 Resumo Semanal — ${new Date().toLocaleDateString('pt-BR')}`
  : `🗓️ Resumo do Dia — ${new Date().toLocaleDateString('pt-BR')}`;

return [{ json: { mensagem, assunto, tipo, totalEventos, dataFormatada } }];

// Mensagem quando não há eventos no período
const periodo = $('Code - Determinar Período').first().json;
const { tipo, dataFormatada } = periodo;

const emoji = tipo === 'SEMANAL' ? '📅' : '🗓️';
const tituloPrincipal = tipo === 'SEMANAL'
  ? `${emoji} *RESUMO SEMANAL*`
  : `${emoji} *RESUMO DO DIA*`;

const separador = '─────────────────';

const mensagem = `${tituloPrincipal}\n${dataFormatada}\n${separador}\n\n✅ *Nenhum compromisso agendado*\n\nNão há compromissos registrados para este período.\nAproveite para se organizar! 😊\n\n${separador}\n✉️ Gerado automaticamente pela sua Assistente Virtual`;

const assunto = tipo === 'SEMANAL'
  ? `📅 Resumo Semanal — Sem compromissos — ${new Date().toLocaleDateString('pt-BR')}`
  : `🗓️ Resumo do Dia — Sem compromissos — ${new Date().toLocaleDateString('pt-BR')}`;

return [{ json: { mensagem, assunto, tipo, totalEventos: 0, dataFormatada } }];
